Reference:
from collections import deque


def hours_to_freeze(grid: list[list[int]]) -> int:
    """0 = gravel walkway, 1 = healthy seedling, 2 = frostbitten seedling.
    Frost spreads orthogonally once per hour. Return hours until no healthy
    seedling remains, or -1 if some seedling can never be reached."""
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    q = deque()
    healthy = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                q.append((r, c))
            elif grid[r][c] == 1:
                healthy += 1
    if healthy == 0:
        return 0
    hours = 0
    while q and healthy:
        hours += 1
        for _ in range(len(q)):
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                    grid[nr][nc] = 2
                    healthy -= 1
                    q.append((nr, nc))
    return hours if healthy == 0 else -1

